// Package store owns the SQLite connection and the schema of the deployment records.
package store

import (
	"database/sql"
	"errors"
	"fmt"
	"sync"

	_ "modernc.org/sqlite"
)

// Error codes returned to clients. Every response that is not a success carries exactly one of these.
const (
	CodeInvalidRequest      = "invalid_request"
	CodeNotFound            = "not_found"
	CodeConflict            = "conflict"
	CodeStorageUnavailable  = "storage_unavailable"
	CodeInvalidReleaseInput = "invalid_release_input"
	CodeReleaseNotFound     = "release_not_found"
	CodeEnvironmentNotFound = "environment_not_found"
	CodeReleaseConflict     = "release_conflict"
	CodeComparisonConflict  = "comparison_conflict"
)

// Error is the JSON shape of a failed request as described in README.md.
type Error struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

func (e *Error) Error() string { return e.Code + ": " + e.Message }

// NewError builds a client-visible error. Messages must stay free of SQL, file paths and stack traces.
func NewError(code, message string) *Error { return &Error{Code: code, Message: message} }

// Is reports whether err carries the given client-visible code.
func Is(err error, code string) bool {
	var target *Error
	return errors.As(err, &target) && target.Code == code
}

// Store is the persistence handle shared by the HTTP layer.
type Store struct {
	db *sql.DB

	// releaseGates serializes concurrent release-record submissions for the
	// same (environment, version) pair. One gate per key, never deleted.
	releaseGates sync.Map
}

// Open connects to the SQLite file and applies the schema.
func Open(path string) (*Store, error) {
	if path == "" {
		return nil, fmt.Errorf("store: database path is empty")
	}
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("store: open %s: %w", path, err)
	}
	db.SetMaxOpenConns(1)
	store := &Store{db: db}
	if err := store.migrate(); err != nil {
		db.Close()
		return nil, err
	}
	return store, nil
}

// Close releases the connection.
func (s *Store) Close() error {
	if s == nil || s.db == nil {
		return nil
	}
	return s.db.Close()
}

// Ping reports whether the database answers.
func (s *Store) Ping() error {
	if s == nil || s.db == nil {
		return NewError(CodeStorageUnavailable, "database is not available")
	}
	if err := s.db.Ping(); err != nil {
		return NewError(CodeStorageUnavailable, "database is not available")
	}
	return nil
}

// migrate creates the tables this service owns. It is idempotent.
func (s *Store) migrate() error {
	const schema = `
CREATE TABLE IF NOT EXISTS deployments (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  name        TEXT    NOT NULL,
  environment TEXT    NOT NULL,
  version     TEXT    NOT NULL,
  created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
`
	if _, err := s.db.Exec(schema); err != nil {
		return fmt.Errorf("store: migrate: %w", err)
	}
	// Columns added after the initial schema. Existing databases gain them one
	// by one; rows written before this change keep NULL and stay readable.
	additions := []struct{ column, statement string }{
		{"changes_json", `ALTER TABLE deployments ADD COLUMN changes_json TEXT`},
		{"gate_status", `ALTER TABLE deployments ADD COLUMN gate_status TEXT`},
		{"rollback_point", `ALTER TABLE deployments ADD COLUMN rollback_point TEXT`},
	}
	for _, addition := range additions {
		exists, err := s.columnExists("deployments", addition.column)
		if err != nil {
			return fmt.Errorf("store: migrate: %w", err)
		}
		if exists {
			continue
		}
		if _, err := s.db.Exec(addition.statement); err != nil {
			return fmt.Errorf("store: migrate: %w", err)
		}
	}
	const trackedSchema = `
CREATE TABLE IF NOT EXISTS tracked_environments (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  environment   TEXT    NOT NULL UNIQUE,
  display_name  TEXT    NOT NULL DEFAULT '',
  registered_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
CREATE TABLE IF NOT EXISTS release_records (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  public_id      TEXT    NOT NULL UNIQUE,
  environment    TEXT    NOT NULL,
  version        TEXT    NOT NULL,
  batch_id       TEXT    NOT NULL DEFAULT '',
  gate_status    TEXT    NOT NULL,
  rollback_point TEXT    NOT NULL,
  recorded_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
CREATE TABLE IF NOT EXISTS release_change_entries (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  record_id   INTEGER NOT NULL REFERENCES release_records(id),
  sequence_no INTEGER NOT NULL,
  category    TEXT    NOT NULL,
  title       TEXT    NOT NULL,
  description TEXT    NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS release_gate_evaluations (
  id                     INTEGER PRIMARY KEY AUTOINCREMENT,
  record_id              INTEGER NOT NULL UNIQUE REFERENCES release_records(id),
  gate_status            TEXT    NOT NULL,
  effective_gate_status  TEXT    NOT NULL
);
CREATE TABLE IF NOT EXISTS release_gate_checks (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  evaluation_id  INTEGER NOT NULL REFERENCES release_gate_evaluations(id),
  check_name     TEXT    NOT NULL,
  check_status   TEXT    NOT NULL,
  evidence       TEXT    NOT NULL,
  waiver_reason  TEXT    NOT NULL DEFAULT '',
  UNIQUE (evaluation_id, check_name)
);
CREATE TABLE IF NOT EXISTS promotion_routes (
  id   INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT    NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS promotion_route_environments (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  route_id    INTEGER NOT NULL REFERENCES promotion_routes(id),
  position    INTEGER NOT NULL,
  environment TEXT    NOT NULL,
  UNIQUE (route_id, position),
  UNIQUE (route_id, environment)
);
CREATE TABLE IF NOT EXISTS release_batch_routes (
  batch_id TEXT    PRIMARY KEY,
  route_id INTEGER NOT NULL REFERENCES promotion_routes(id)
);
`
	if _, err := s.db.Exec(trackedSchema); err != nil {
		return fmt.Errorf("store: migrate: %w", err)
	}
	batchColumnExists, err := s.columnExists("release_records", "batch_id")
	if err != nil {
		return fmt.Errorf("store: migrate: %w", err)
	}
	if !batchColumnExists {
		if _, err := s.db.Exec(`ALTER TABLE release_records ADD COLUMN batch_id TEXT NOT NULL DEFAULT ''`); err != nil {
			return fmt.Errorf("store: migrate: %w", err)
		}
	}
	// Databases created before release batches kept a table-level
	// UNIQUE (environment, version) constraint. Batched records must stay
	// isolated per batch identifier, so that constraint is replaced by two
	// partial unique indexes: one covering legacy unbatched rows and one
	// scoping (environment, version) duplicates inside a single batch.
	if err := s.migrateReleaseBatchIndexes(); err != nil {
		return err
	}
	return nil
}

// migrateReleaseBatchIndexes swaps the old UNIQUE (environment, version)
// table constraint for batch-aware partial unique indexes. It is idempotent.
func (s *Store) migrateReleaseBatchIndexes() error {
	rows, err := s.db.Query(`PRAGMA index_list('release_records')`)
	if err != nil {
		return fmt.Errorf("store: migrate: %w", err)
	}
	type indexInfo struct {
		name   string
		unique int
		origin string
	}
	var indexes []indexInfo
	for rows.Next() {
		var seq, unique int
		var name, origin, partial sql.NullString
		if err := rows.Scan(&seq, &name, &unique, &origin, &partial); err != nil {
			rows.Close()
			return fmt.Errorf("store: migrate: %w", err)
		}
		indexes = append(indexes, indexInfo{name: name.String, unique: unique, origin: origin.String})
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return fmt.Errorf("store: migrate: %w", err)
	}
	needsRebuild := false
	for _, index := range indexes {
		// Origin "u" marks an index created by a table UNIQUE constraint;
		// SQLite cannot drop such an index directly, so the table is rebuilt.
		if index.origin != "u" || index.unique != 1 {
			continue
		}
		columns, err := s.indexColumns(index.name)
		if err != nil {
			return err
		}
		if len(columns) == 2 && columns[0] == "environment" && columns[1] == "version" {
			needsRebuild = true
		}
	}
	if needsRebuild {
		const rebuild = `
CREATE TABLE release_records_new (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  public_id      TEXT    NOT NULL UNIQUE,
  environment    TEXT    NOT NULL,
  version        TEXT    NOT NULL,
  batch_id       TEXT    NOT NULL DEFAULT '',
  gate_status    TEXT    NOT NULL,
  rollback_point TEXT    NOT NULL,
  recorded_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))
);
INSERT INTO release_records_new
  (id, public_id, environment, version, batch_id, gate_status, rollback_point, recorded_at)
  SELECT id, public_id, environment, version, batch_id, gate_status, rollback_point, recorded_at
  FROM release_records;
DROP TABLE release_records;
ALTER TABLE release_records_new RENAME TO release_records;
`
		if _, err := s.db.Exec(rebuild); err != nil {
			return fmt.Errorf("store: migrate: %w", err)
		}
	}
	const partialIndexes = `
CREATE UNIQUE INDEX IF NOT EXISTS release_records_env_version_unbatched
  ON release_records (environment, version) WHERE batch_id = '';
CREATE UNIQUE INDEX IF NOT EXISTS release_records_env_version_batch
  ON release_records (environment, version, batch_id) WHERE batch_id != '';
`
	if _, err := s.db.Exec(partialIndexes); err != nil {
		return fmt.Errorf("store: migrate: %w", err)
	}
	return nil
}

// indexColumns returns the columns covered by an index in index order.
func (s *Store) indexColumns(indexName string) ([]string, error) {
	rows, err := s.db.Query(`PRAGMA index_info('` + indexName + `')`)
	if err != nil {
		return nil, fmt.Errorf("store: migrate: %w", err)
	}
	defer rows.Close()
	var columns []string
	for rows.Next() {
		var tableOffset, columnOrder int
		var name sql.NullString
		if err := rows.Scan(&tableOffset, &columnOrder, &name); err != nil {
			return nil, fmt.Errorf("store: migrate: %w", err)
		}
		columns = append(columns, name.String)
	}
	return columns, rows.Err()
}

// columnExists reports whether the named column is present on the table.
func (s *Store) columnExists(table, column string) (bool, error) {
	rows, err := s.db.Query(`PRAGMA table_info(` + table + `)`)
	if err != nil {
		return false, err
	}
	defer rows.Close()
	for rows.Next() {
		var cid, notNull, pk int
		var name, columnType string
		var defaultValue sql.NullString
		if err := rows.Scan(&cid, &name, &columnType, &notNull, &defaultValue, &pk); err != nil {
			return false, err
		}
		if name == column {
			return true, nil
		}
	}
	return false, rows.Err()
}
package store

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"strings"
)

// ChangeEntry is one structured change attached to a release record.
type ChangeEntry struct {
	Sequence    int    `json:"sequence"`
	Category    string `json:"category"`
	Title       string `json:"title"`
	Description string `json:"description"`
}

// ReleaseRecord is one traceable release record with structured change
// entries and an opaque rollback point identifier.
type ReleaseRecord struct {
	ID            int64
	PublicID      string
	Environment   string
	Version       string
	BatchID       string
	GateStatus    string
	RollbackPoint string
	Changes       []ChangeEntry
	RecordedAt    string
}

// ReleaseRecordFilter narrows ListReleaseRecords. Zero-valued fields are
// ignored; From/To are inclusive second-precision UTC bounds.
type ReleaseRecordFilter struct {
	Environment string
	Version     string
	BatchID     string
	GateStatus  string
	From        string
	To          string
}

// ChangeEntryFilter narrows ListChangeEntries. Empty fields are ignored;
// From/To are inclusive second-precision UTC bounds on recorded_at.
type ChangeEntryFilter struct {
	Environment string
	Version     string
	BatchID     string
	Category    string
	Title       string
	GateStatus  string
	From        string
	To          string
}

// ChangeEntryItem is one structured change entry joined with the public
// fields of the release record it belongs to. Only release-records changes
// are represented here; baseline POST /releases changes never appear.
type ChangeEntryItem struct {
	RecordID      int64
	RecordedAt    string
	EntryID       int64
	Entry         ChangeEntry
	PublicID      string
	Environment   string
	Version       string
	BatchID       string
	GateStatus    string
	RollbackPoint string
}

const releaseRecordColumns = `public_id, environment, version, batch_id, gate_status, rollback_point, recorded_at`

// ErrReleaseAlreadyExists marks a duplicate (environment, version) submission.
type ErrReleaseAlreadyExists struct {
	Environment string
	Version     string
}

func (e *ErrReleaseAlreadyExists) Error() string {
	return "release record " + e.Environment + " " + e.Version + " already exists"
}

// InsertReleaseRecord stores one release record, generating the stable public
// identifier and server-side recorded_at. A duplicate (environment, version)
// pair returns *ErrReleaseAlreadyExists.
func (s *Store) InsertReleaseRecord(record *ReleaseRecord) error {
	// The batch-aware partial indexes keep unbatched rows unique on
	// (environment, version) and batched rows unique per batch. Rows of the
	// other batch flavor sharing the same environment and version still
	// represent the same single effective release, so they conflict too.
	//
	// Sequential reuse of an environment and version across distinct batches
	// stays legal, but several submissions arriving at the same time for the
	// same (environment, version) pair form one concurrent wave: exactly one
	// request may create the record and the rest conflict, so two requests can
	// never pass the duplicate check side by side. The in-process gate catches
	// that race; the database transaction below covers every other storage
	// failure and rolls the whole write back as a unit.
	gate := s.acquireReleaseGate(record.Environment, record.Version)
	return gate.run(func(contended bool) error {
		return s.insertReleaseRecordTx(record, contended)
	})
}

// insertReleaseRecordTx performs the duplicate check, the main row insert and
// every change-entry insert inside one immediate transaction. Any failure
// rolls the transaction back, leaving no half-written record behind. When
// contended is true the call lost a concurrent submission race, so the check
// ignores batch boundaries: only one record per (environment, version) may
// survive a single concurrent wave.
func (s *Store) insertReleaseRecordTx(record *ReleaseRecord, contended bool) error {
	tx, err := s.db.Begin()
	if err != nil {
		return fmt.Errorf("store: begin release record tx: %w", err)
	}
	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback()
		}
	}()

	checkQuery := `SELECT count(1) FROM release_records
		WHERE environment = ? AND version = ?
		  AND (batch_id = '' OR ? = '')
		  AND batch_id != ?`
	if contended {
		checkQuery = `SELECT count(1) FROM release_records
			WHERE environment = ? AND version = ?`
	}
	var existing int
	if err := tx.QueryRow(
		checkQuery, record.Environment, record.Version, record.BatchID, record.BatchID,
	).Scan(&existing); err != nil {
		return fmt.Errorf("store: check release record: %w", err)
	}
	if existing > 0 {
		return &ErrReleaseAlreadyExists{Environment: record.Environment, Version: record.Version}
	}

	const maxAttempts = 3
	var lastErr error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		id, err := newPublicID()
		if err != nil {
			return fmt.Errorf("store: new release id: %w", err)
		}
		res, err := tx.Exec(
			`INSERT INTO release_records (public_id, environment, version, batch_id, gate_status, rollback_point)
			 VALUES (?, ?, ?, ?, ?, ?)`,
			id, record.Environment, record.Version, record.BatchID, record.GateStatus, record.RollbackPoint,
		)
		if err != nil {
			if isUniqueViolation(err) {
				message := strings.ToLower(err.Error())
				if strings.Contains(message, "release_records.environment") ||
					strings.Contains(message, "release_records_env_version") {
					return &ErrReleaseAlreadyExists{Environment: record.Environment, Version: record.Version}
				}
				lastErr = err
				continue
			}
			return fmt.Errorf("store: insert release record: %w", err)
		}
		rowID, err := res.LastInsertId()
		if err != nil {
			return fmt.Errorf("store: insert release record: %w", err)
		}
		if releaseInsertFaultHook != nil {
			if err := releaseInsertFaultHook(record, attempt, rowID); err != nil {
				return fmt.Errorf("store: insert change entry: %w", err)
			}
		}
		for i := range record.Changes {
			if _, err := tx.Exec(
				`INSERT INTO release_change_entries (record_id, sequence_no, category, title, description)
				 VALUES (?, ?, ?, ?, ?)`,
				rowID, record.Changes[i].Sequence, record.Changes[i].Category,
				record.Changes[i].Title, record.Changes[i].Description,
			); err != nil {
				return fmt.Errorf("store: insert change entry: %w", err)
			}
		}
		if err := tx.Commit(); err != nil {
			return fmt.Errorf("store: commit release record: %w", err)
		}
		committed = true

		stored, err := s.GetReleaseRecord(id)
		if err != nil {
			return err
		}
		*record = *stored
		return nil
	}
	return fmt.Errorf("store: insert release record: %w", lastErr)
}

// GetReleaseRecord returns one record by its stable public identifier, or
// (nil, nil) when it does not exist.
func (s *Store) GetReleaseRecord(publicID string) (*ReleaseRecord, error) {
	rows, err := s.queryReleaseRecords(
		`SELECT r.id, r.`+strings.ReplaceAll(releaseRecordColumns, ", ", ", r.")+
			`, e.sequence_no, e.category, e.title, e.description
		 FROM release_records r
		 LEFT JOIN release_change_entries e ON e.record_id = r.id
		 WHERE r.public_id = ?
		 ORDER BY r.id DESC, e.sequence_no ASC, e.id ASC`,
		publicID,
	)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return nil, nil
	}
	return &rows[0], nil
}

// ListReleaseRecords returns matching records newest first. Records sharing a
// recorded_at timestamp break ties by their internal id descending, keeping
// the order deterministic and identical to registration order.
func (s *Store) ListReleaseRecords(filter ReleaseRecordFilter) ([]ReleaseRecord, error) {
	var where []string
	var args []any
	if filter.Environment != "" {
		where = append(where, `r.environment = ?`)
		args = append(args, filter.Environment)
	}
	if filter.Version != "" {
		where = append(where, `r.version = ?`)
		args = append(args, filter.Version)
	}
	if filter.BatchID != "" {
		where = append(where, `r.batch_id = ?`)
		args = append(args, filter.BatchID)
	}
	if filter.GateStatus != "" {
		where = append(where, `r.gate_status = ?`)
		args = append(args, filter.GateStatus)
	}
	if filter.From != "" {
		where = append(where, `r.recorded_at >= ?`)
		args = append(args, filter.From)
	}
	if filter.To != "" {
		where = append(where, `r.recorded_at <= ?`)
		args = append(args, filter.To)
	}
	query := `SELECT r.id, r.` + strings.ReplaceAll(releaseRecordColumns, ", ", ", r.") +
		`, e.sequence_no, e.category, e.title, e.description
		 FROM release_records r
		 LEFT JOIN release_change_entries e ON e.record_id = r.id`
	if len(where) > 0 {
		query += ` WHERE ` + strings.Join(where, ` AND `)
	}
	query += ` ORDER BY r.recorded_at DESC, r.id DESC, e.sequence_no ASC, e.id ASC`
	return s.queryReleaseRecords(query, args...)
}

// ListReleaseRecordsPage returns one keyset page of records matching filter
// in the same newest-first order ListReleaseRecords uses. The anchor marks
// the last record already returned (recorded_at desc, internal id desc for
// same-second ties); zero anchor values request the first page. Up to
// limit+1 records are fetched so the caller can detect a following page.
//
// Keyset paging makes the walk stable against concurrent inserts: rows added
// after the first request sort ahead of every anchor and never enter a later
// page, so already-seen records are neither repeated nor skipped.
func (s *Store) ListReleaseRecordsPage(
	filter ReleaseRecordFilter,
	anchorRecordedAt string,
	anchorID int64,
	limit int,
) ([]ReleaseRecord, error) {
	where := []string{}
	args := []any{}
	if filter.Environment != "" {
		where = append(where, `environment = ?`)
		args = append(args, filter.Environment)
	}
	if filter.Version != "" {
		where = append(where, `version = ?`)
		args = append(args, filter.Version)
	}
	if filter.BatchID != "" {
		where = append(where, `batch_id = ?`)
		args = append(args, filter.BatchID)
	}
	if filter.GateStatus != "" {
		where = append(where, `gate_status = ?`)
		args = append(args, filter.GateStatus)
	}
	if filter.From != "" {
		where = append(where, `recorded_at >= ?`)
		args = append(args, filter.From)
	}
	if filter.To != "" {
		where = append(where, `recorded_at <= ?`)
		args = append(args, filter.To)
	}
	if anchorID > 0 {
		where = append(where, `(recorded_at < ? OR (recorded_at = ? AND id < ?))`)
		args = append(args, anchorRecordedAt, anchorRecordedAt, anchorID)
	}
	query := `SELECT r.id, r.` + strings.ReplaceAll(releaseRecordColumns, ", ", ", r.") +
		`, e.sequence_no, e.category, e.title, e.description
		 FROM (
		   SELECT id, recorded_at FROM release_records`
	if len(where) > 0 {
		query += ` WHERE ` + strings.Join(where, ` AND `)
	}
	query += ` ORDER BY recorded_at DESC, id DESC LIMIT ?
		 ) AS page
		 JOIN release_records r ON r.id = page.id
		 LEFT JOIN release_change_entries e ON e.record_id = r.id
		 ORDER BY page.recorded_at DESC, page.id DESC, e.sequence_no ASC, e.id ASC`
	args = append(args, limit+1)
	return s.queryReleaseRecords(query, args...)
}

// ResolveReleaseRecordPosition maps a record's stable public identifier to
// its internal keyset position (recorded_at, internal id). Records are
// immutable and never deleted, so a position resolved for a cursor keeps
// pointing at the same row. It returns ok == false when no record exists.
func (s *Store) ResolveReleaseRecordPosition(publicID string) (recordedAt string, id int64, ok bool, err error) {
	err = s.db.QueryRow(
		`SELECT recorded_at, id FROM release_records WHERE public_id = ?`, publicID,
	).Scan(&recordedAt, &id)
	if err == sql.ErrNoRows {
		return "", 0, false, nil
	}
	if err != nil {
		return "", 0, false, fmt.Errorf("store: resolve release record position: %w", err)
	}
	return recordedAt, id, true, nil
}

// EffectiveReleaseRecord returns the newest record for an environment and
// version, or (nil, nil) when absent. The (environment, version) pair is
// unique for new records, but this keeps the same "latest wins" read
// semantics the baseline API uses.
func (s *Store) EffectiveReleaseRecord(environment, version string) (*ReleaseRecord, error) {
	rows, err := s.queryReleaseRecords(
		`SELECT r.id, r.`+strings.ReplaceAll(releaseRecordColumns, ", ", ", r.")+
			`, e.sequence_no, e.category, e.title, e.description
		 FROM release_records r
		 LEFT JOIN release_change_entries e ON e.record_id = r.id
		 WHERE r.environment = ? AND r.version = ?
		 ORDER BY r.id DESC, e.sequence_no ASC, e.id ASC`,
		environment, version,
	)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return nil, nil
	}
	return &rows[0], nil
}

// ListLatestReleaseRecords returns the up to limit newest records of an
// environment recorded at or before asOf (an inclusive second-precision UTC
// bound; an empty bound disables the cutoff). Ordering follows
// current/previous release-state selection: recorded_at descending, then
// insertion id descending so same-timestamp writes keep write order. Each
// returned record carries its change entries.
func (s *Store) ListLatestReleaseRecords(environment, asOf string, limit int) ([]ReleaseRecord, error) {
	query := `SELECT r.id, r.` + strings.ReplaceAll(releaseRecordColumns, ", ", ", r.") +
		`, e.sequence_no, e.category, e.title, e.description
		 FROM (
		   SELECT id, recorded_at FROM release_records
		   WHERE environment = ?`
	args := []any{environment}
	if asOf != "" {
		query += ` AND recorded_at <= ?`
		args = append(args, asOf)
	}
	query += `
		   ORDER BY recorded_at DESC, id DESC LIMIT ?
		 ) AS page
		 JOIN release_records r ON r.id = page.id
		 LEFT JOIN release_change_entries e ON e.record_id = r.id
		 ORDER BY page.recorded_at DESC, page.id DESC, e.sequence_no ASC, e.id ASC`
	args = append(args, limit)
	return s.queryReleaseRecords(query, args...)
}

// EffectiveReleaseRecordAsOf resolves the newest record for an environment
// and version exactly as EffectiveReleaseRecord does, but only records
// recorded at or before asOf (inclusive second-precision UTC bound) qualify.
// It returns (nil, nil) when no in-range record exists.
func (s *Store) EffectiveReleaseRecordAsOf(environment, version, asOf string) (*ReleaseRecord, error) {
	rows, err := s.queryReleaseRecords(
		`SELECT r.id, r.`+strings.ReplaceAll(releaseRecordColumns, ", ", ", r.")+
			`, e.sequence_no, e.category, e.title, e.description
		 FROM release_records r
		 LEFT JOIN release_change_entries e ON e.record_id = r.id
		 WHERE r.environment = ? AND r.version = ? AND r.recorded_at <= ?
		 ORDER BY r.id DESC, e.sequence_no ASC, e.id ASC`,
		environment, version, asOf,
	)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return nil, nil
	}
	return &rows[0], nil
}

// ListReleaseRecordHistory returns one page of an environment's records in
// the order history pages follow: recorded_at descending, then insertion id
// descending. The keyset anchor (afterRecordedAt, afterID) marks the last row
// already returned; zero values request the first page. Up to limit+1 rows are
// fetched so the caller can detect a following page.
func (s *Store) ListReleaseRecordHistory(environment string, afterRecordedAt string, afterID int64, limit int) ([]ReleaseRecord, error) {
	query := `SELECT r.id, r.` + strings.ReplaceAll(releaseRecordColumns, ", ", ", r.") +
		`, e.sequence_no, e.category, e.title, e.description
		 FROM (
		   SELECT id, recorded_at FROM release_records
		   WHERE environment = ?`
	args := []any{environment}
	if afterID > 0 {
		query += ` AND (recorded_at < ? OR (recorded_at = ? AND id < ?))`
		args = append(args, afterRecordedAt, afterRecordedAt, afterID)
	}
	query += ` ORDER BY recorded_at DESC, id DESC LIMIT ?
		 ) AS page
		 JOIN release_records r ON r.id = page.id
		 LEFT JOIN release_change_entries e ON e.record_id = r.id
		 ORDER BY page.recorded_at DESC, page.id DESC, e.sequence_no ASC, e.id ASC`
	args = append(args, limit+1)
	return s.queryReleaseRecords(query, args...)
}

// queryReleaseRecords runs a joined query and assembles records with their
// change entries. Rows must arrive ordered record (descending) then entry.
func (s *Store) queryReleaseRecords(query string, args ...any) ([]ReleaseRecord, error) {
	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, fmt.Errorf("store: query release records: %w", err)
	}
	defer rows.Close()
	records := []ReleaseRecord{}
	indexByID := map[string]int{}
	for rows.Next() {
		var record ReleaseRecord
		var sequence sql.NullInt64
		var category, title, description sql.NullString
		if err := rows.Scan(
			&record.ID, &record.PublicID, &record.Environment, &record.Version, &record.BatchID, &record.GateStatus,
			&record.RollbackPoint, &record.RecordedAt,
			&sequence, &category, &title, &description,
		); err != nil {
			return nil, fmt.Errorf("store: scan release record: %w", err)
		}
		pos, seen := indexByID[record.PublicID]
		if !seen {
			record.Changes = []ChangeEntry{}
			records = append(records, record)
			pos = len(records) - 1
			indexByID[record.PublicID] = pos
		}
		if sequence.Valid {
			records[pos].Changes = append(records[pos].Changes, ChangeEntry{
				Sequence:    int(sequence.Int64),
				Category:    category.String,
				Title:       title.String,
				Description: description.String,
			})
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: query release records: %w", err)
	}
	return records, nil
}

// newPublicID returns an opaque stable identifier for a release record.
func newPublicID() (string, error) {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", err
	}
	return "rel_" + hex.EncodeToString(buf), nil
}

// isUniqueViolation reports whether err is a SQLite UNIQUE constraint failure.
func isUniqueViolation(err error) bool {
	if err == nil {
		return false
	}
	message := strings.ToLower(err.Error())
	return strings.Contains(message, "constraint failed") && strings.Contains(message, "unique")
}

// ReleaseBatchExists reports whether at least one release record is stored
// for the given batch identifier.
func (s *Store) ReleaseBatchExists(batchID string) (bool, error) {
	var count int
	if err := s.db.QueryRow(
		`SELECT count(1) FROM release_records WHERE batch_id = ?`, batchID,
	).Scan(&count); err != nil {
		return false, fmt.Errorf("store: check release batch: %w", err)
	}
	return count > 0, nil
}

// ListChangeEntries returns one page of structured change entries matching
// the filter. Entries are ordered by the owning release newest first
// (recorded_at descending, internal record id descending to break
// same-second ties in write order) and inside a release by sequence then
// title ascending. The keyset anchor marks the last entry already returned;
// zero values request the first page. Up to limit+1 rows are fetched so the
// caller can detect a following page.
func (s *Store) ListChangeEntries(
	filter ChangeEntryFilter,
	anchor ChangeEntryItem,
	limit int,
) ([]ChangeEntryItem, error) {
	where := []string{}
	args := []any{}
	if filter.Environment != "" {
		where = append(where, `r.environment = ?`)
		args = append(args, filter.Environment)
	}
	if filter.Version != "" {
		where = append(where, `r.version = ?`)
		args = append(args, filter.Version)
	}
	if filter.BatchID != "" {
		where = append(where, `r.batch_id = ?`)
		args = append(args, filter.BatchID)
	}
	if filter.Category != "" {
		where = append(where, `e.category = ?`)
		args = append(args, filter.Category)
	}
	if filter.Title != "" {
		where = append(where, `e.title = ?`)
		args = append(args, filter.Title)
	}
	if filter.GateStatus != "" {
		where = append(where, `r.gate_status = ?`)
		args = append(args, filter.GateStatus)
	}
	if filter.From != "" {
		where = append(where, `r.recorded_at >= ?`)
		args = append(args, filter.From)
	}
	if filter.To != "" {
		where = append(where, `r.recorded_at <= ?`)
		args = append(args, filter.To)
	}
	if anchor.RecordID > 0 {
		where = append(where,
			`(r.recorded_at < ?
			  OR (r.recorded_at = ? AND r.id < ?)
			  OR (r.recorded_at = ? AND r.id = ? AND
			      (e.sequence_no > ? OR (e.sequence_no = ? AND e.title > ?))))`)
		args = append(args,
			anchor.RecordedAt,
			anchor.RecordedAt, anchor.RecordID,
			anchor.RecordedAt, anchor.RecordID,
			anchor.Entry.Sequence, anchor.Entry.Sequence, anchor.Entry.Title,
		)
	}
	query := `SELECT r.id, r.public_id, r.environment, r.version, r.batch_id,
	                 r.gate_status, r.rollback_point, r.recorded_at,
	                 e.id, e.sequence_no, e.category, e.title, e.description
	          FROM release_change_entries e
	          JOIN release_records r ON r.id = e.record_id`
	if len(where) > 0 {
		query += ` WHERE ` + strings.Join(where, ` AND `)
	}
	query += ` ORDER BY r.recorded_at DESC, r.id DESC, e.sequence_no ASC, e.title ASC, e.id ASC
	           LIMIT ?`
	args = append(args, limit+1)

	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, fmt.Errorf("store: query change entries: %w", err)
	}
	defer rows.Close()
	items := []ChangeEntryItem{}
	for rows.Next() {
		var item ChangeEntryItem
		if err := rows.Scan(
			&item.RecordID, &item.PublicID, &item.Environment, &item.Version, &item.BatchID,
			&item.GateStatus, &item.RollbackPoint, &item.RecordedAt,
			&item.EntryID, &item.Entry.Sequence, &item.Entry.Category,
			&item.Entry.Title, &item.Entry.Description,
		); err != nil {
			return nil, fmt.Errorf("store: scan change entry: %w", err)
		}
		items = append(items, item)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: query change entries: %w", err)
	}
	return items, nil
}

