	}
	signature, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return releaseBatchCursor{}, false
	}
	mac := hmac.New(sha256.New, releaseBatchCursorSigningKey)
	mac.Write(payload)
	if !hmac.Equal(signature, mac.Sum(nil)) {
