func TestListReleaseBatchesSummaries(t *testing.T) {
	router, db := newChangeTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	registerEnvironmentOK(t, router, "dev")
	createRecordOK(t, router, changeRecordBody("dev", "1.0.0", "allowed", "rb:1", "b-zeta",
		entryMap(1, "feature", "alpha", "a"), entryMap(2, "fix", "beta", "b")))
	pinRecordedAt(t, db, "dev", "1.0.0", "2026-10-01T08:00:00Z")
	createRecordOK(t, router, changeRecordBody("dev", "1.1.0", "blocked", "rb:2", "b-zeta",
		entryMap(1, "feature", "gamma", "c")))
	pinRecordedAt(t, db, "dev", "1.1.0", "2026-10-01T09:00:00Z")
	createRecordOK(t, router, changeRecordBody("prod", "1.1.0", "pending", "rb:3", "b-zeta",
		entryMap(1, "fix", "delta", "d")))
	pinRecordedAt(t, db, "prod", "1.1.0", "2026-10-01T10:00:00Z")
	createRecordOK(t, router, changeRecordBody("dev", "2.0.0", "allowed", "rb:4", "b-alpha",
		entryMap(1, "feature", "epsilon", "e")))
	pinRecordedAt(t, db, "dev", "2.0.0", "2026-10-01T11:00:00Z")
	createRecordOK(t, router, changeRecordBody("prod", "9.0.0", "allowed", "rb:9", "",
		entryMap(1, "fix", "unbatched", "u")))

	recorder := doRequest(t, router, http.MethodGet, "/api/v1/release-batches", "")
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d, %s", recorder.Code, recorder.Body.String())
	}
	body := decodeBody(t, recorder)
	if len(body) != 2 {
		t.Fatalf("only batches and next_cursor keys allowed: %s", recorder.Body.String())
	}
	if _, ok := body["next_cursor"]; !ok {
		t.Fatalf("next_cursor must be present (null on the last page): %s", recorder.Body.String())
	}
	if body["next_cursor"] != nil {
		t.Fatalf("single page next_cursor = %v, want null", body["next_cursor"])
	}
	rawBatches, ok := body["batches"].([]any)
	if !ok || len(rawBatches) != 2 {
		t.Fatalf("batches = %v, want exactly b-alpha and b-zeta", body["batches"])
	}
	first := rawBatches[0].(map[string]any)
	second := rawBatches[1].(map[string]any)
	if first["batch_id"] != "b-alpha" || second["batch_id"] != "b-zeta" {
		t.Fatalf("order = %v then %v, want last_recorded_at desc", first["batch_id"], second["batch_id"])
	}
	if first["last_recorded_at"] != "2026-10-01T11:00:00Z" {
		t.Fatalf("last_recorded_at = %v", first["last_recorded_at"])
	}
	if second["release_count"].(float64) != 3 {
		t.Fatalf("release_count = %v, want 3", second["release_count"])
	}
	if second["change_count"].(float64) != 4 {
		t.Fatalf("change_count = %v, want 4 across every batch record", second["change_count"])
	}
	environments, _ := second["environments"].([]any)
	if len(environments) != 2 || environments[0] != "dev" || environments[1] != "prod" {
		t.Fatalf("environments = %v, want sorted unique [dev prod]", environments)
	}
	gates := second["gate_counts"].(map[string]any)
	if gates["allowed"].(float64) != 1 || gates["blocked"].(float64) != 1 || gates["pending"].(float64) != 1 {
		t.Fatalf("gate_counts = %v, want 1/1/1", gates)
	}
	if !strings.Contains(recorder.Body.String(), `"environments":[]`) && strings.Contains(recorder.Body.String(), `"environments":null`) {
		t.Fatalf("environments must serialize as [] not null: %s", recorder.Body.String())
	}
}

