func TestListReleaseBatchesFiltersAreAND(t *testing.T) {
	router, db := newChangeTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	registerEnvironmentOK(t, router, "dev")
	createRecordOK(t, router, changeRecordBody("dev", "1.0.0", "allowed", "rb:1", "b-zeta"))
	pinRecordedAt(t, db, "dev", "1.0.0", "2026-10-01T08:00:00Z")
	createRecordOK(t, router, changeRecordBody("prod", "1.1.0", "blocked", "rb:2", "b-zeta"))
	pinRecordedAt(t, db, "prod", "1.1.0", "2026-10-01T09:00:00Z")

	cases := []struct {
		query string
		want  []string
	}{
		{"?environment=dev", []string{"b-zeta"}},
		{"?version=1.1.0", []string{"b-zeta"}},
		{"?gate_status=blocked", []string{"b-zeta"}},
		{"?from=2026-10-01T09:00:00Z", []string{"b-zeta"}},
		{"?to=2026-10-01T08:00:00Z", []string{"b-zeta"}},
		{"?from=2026-10-01&to=2026-10-01", []string{"b-zeta"}},
		{"?environment=prod&gate_status=allowed", []string{}},
		{"?version=1.1.0&environment=dev", []string{}},
	}
	for _, tc := range cases {
		recorder := doRequest(t, router, http.MethodGet, "/api/v1/release-batches"+tc.query, "")
		if recorder.Code != http.StatusOK {
			t.Fatalf("%s status = %d, %s", tc.query, recorder.Code, recorder.Body.String())
		}
		body := decodeBody(t, recorder)
		rawBatches, _ := body["batches"].([]any)
		got := make([]string, 0, len(rawBatches))
		for _, raw := range rawBatches {
			got = append(got, raw.(map[string]any)["batch_id"].(string))
		}
		if strings.Join(got, ",") != strings.Join(tc.want, ",") {
			t.Fatalf("%s batches = %v, want %v", tc.query, got, tc.want)
		}
	}
}

func TestListReleaseBatchesPaginationWalkAndBinding(t *testing.T) {
	router, db := newChangeTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	ids := []string{"b-a", "b-b", "b-c", "b-d", "b-e"}
	for i, batch := range ids {
		createRecordOK(t, router, changeRecordBody("prod", "1.0."+string(rune('0'+i)), "allowed", "rb", batch))
		pinRecordedAt(t, db, "prod", "1.0."+string(rune('0'+i)), "2026-10-01T08:00:00Z")
	}

	path := "/api/v1/release-batches?limit=2"
	var got []string
	cursorCount := 0
	for page := 0; page < 10; page++ {
		recorder := doRequest(t, router, http.MethodGet, path, "")
		if recorder.Code != http.StatusOK {
			t.Fatalf("page %d status = %d, %s", page, recorder.Code, recorder.Body.String())
		}
		body := decodeBody(t, recorder)
		rawBatches, _ := body["batches"].([]any)
		for _, raw := range rawBatches {
			got = append(got, raw.(map[string]any)["batch_id"].(string))
		}
		next := body["next_cursor"]
		if next == nil {
			break
		}
		cursorCount++
		path = "/api/v1/release-batches?limit=2&cursor=" + next.(string)
	}
	want := []string{"b-e", "b-d", "b-c", "b-b", "b-a"}
	if strings.Join(got, ",") != strings.Join(want, ",") {
		t.Fatalf("walk = %v, want %v", got, want)
	}
	if cursorCount != 2 {
		t.Fatalf("five batches with limit 2 need two non-final pages, got %d", cursorCount)
	}

	// A cursor minted under one filter must not be accepted under another.
	recorder := doRequest(t, router, http.MethodGet, "/api/v1/release-batches?limit=2", "")
	firstCursor := decodeBody(t, recorder)["next_cursor"].(string)
	rebound := doRequest(t, router, http.MethodGet,
		"/api/v1/release-batches?gate_status=blocked&cursor="+firstCursor, "")
	wantError(t, rebound, http.StatusBadRequest, "BATCH_QUERY_INVALID")

	// Corrupt payloads and signatures are rejected.
	parts := strings.Split(firstCursor, ".")
	payload, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		t.Fatal(err)
	}
	tampered := base64.RawURLEncoding.EncodeToString(append(payload, 'x')) + "." + parts[1]
	for _, raw := range []string{
		"garbage",
		"a.b.c",
		parts[0] + ".AAAA",
		tampered,
		"." + parts[1],
	} {
		rec := doRequest(t, router, http.MethodGet, "/api/v1/release-batches?cursor="+raw, "")
		wantError(t, rec, http.StatusBadRequest, "BATCH_QUERY_INVALID")
	}
}

